  PublishSafetyState(decision);
}

void SafetyGateNode::PeriodicPublishTick() {
  if (!safe_cmd_vel_pub_) return;

  PeriodicPublishInput in;
  in.estop_or_fault = estop_active_ || auto_fault_latched_;
  in.bumper = bumper_active_;
  in.decision_critical =
      last_decision_.severity == amr_dispatcher_core::safety::SafetySeverity::kCritical;
  in.has_decision = has_decision_;
  in.has_last_raw_stamp = has_raw_cmd_stamp_;
  in.last_raw_stamp = last_raw_cmd_stamp_;
  in.now = std::chrono::steady_clock::now();
  in.heartbeat_timeout = heartbeat_timeout_;
  in.last_linear_x_mps = last_decision_.linear_x_mps;
  in.last_linear_y_mps = last_decision_.linear_y_mps;
  in.last_angular_z_radps = last_decision_.angular_z_radps;

  const auto out = ComputePeriodicPublish(in);
  if (out.kind == PeriodicPublishKind::kSkip) return;

  geometry_msgs::msg::Twist safe_cmd;
  safe_cmd.linear.x = out.linear_x_mps;
  safe_cmd.linear.y = out.linear_y_mps;
  safe_cmd.angular.z = out.angular_z_radps;
  safe_cmd_vel_pub_->publish(safe_cmd);
}

void SafetyGateNode::PublishIdleSafetyState() {
  // 无任何运动指令时构造零速裁决：allowed 由多源健康聚合决定，
  // reason 标注 idle 以便运维区分"门控放行"与"门控阻断"。
  amr_dispatcher_core::safety::CmdVelGateDecision idle;
  const bool effective_estop = estop_active_ || auto_fault_latched_;
  idle.allowed = watchdog_ok_ && !effective_estop && !bumper_active_ && !manual_takeover_active_;
  idle.reason = idle.allowed ? "idle" : "idle_blocked";
  idle.severity = effective_estop || bumper_active_ ? amr_dispatcher_core::safety::SafetySeverity::kCritical
                                                 : (watchdog_ok_ ? amr_dispatcher_core::safety::SafetySeverity::kInfo
                                                                 : amr_dispatcher_core::safety::SafetySeverity::kWarn);
  PublishSafetyState(idle);
}

void SafetyGateNode::PublishSafetyState(const amr_dispatcher_core::safety::CmdVelGateDecision& decision) {
  amr_dispatcher_interfaces::msg::SafetyState state_msg;
  state_msg.header.stamp = now();
  state_msg.motion_allowed = decision.allowed;
  state_msg.reason = decision.reason;

  if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kCritical) {
    state_msg.severity = "CRITICAL";
    state_msg.speed_scale = 0.0;
  } else if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kWarn) {
    state_msg.severity = "WARN";
    state_msg.speed_scale = 0.3;
  } else {
    state_msg.severity = "INFO";
    state_msg.speed_scale = 1.0;
  }

  if (estop_active_ || auto_fault_latched_) state_msg.active_sources.push_back("estop");
  if (bumper_active_) state_msg.active_sources.push_back("bumper");
  if (manual_takeover_active_) state_msg.active_sources.push_back("manual_takeover");
  if (!state_msg.active_sources.empty()) {
    state_msg.active_stop_source = state_msg.active_sources.front();
  }

  safety_state_pub_->publish(state_msg);
}

}  // namespace amr_dispatcher_ros

int main(int argc, char* argv[]) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared<amr_dispatcher_ros::SafetyGateNode>();
  rclcpp::spin(node);
  rclcpp::shutdown();
  return 0;
}

