TEST(ChassisPacketTest, EncodeCommandFixedPrecision) {
  ChassisCommand cmd;
  cmd.linear_x_mps = 0.5;
  cmd.linear_y_mps = 0.0;
  cmd.angular_z_radps = -0.25;
