  EXPECT_FALSE(ParseCommandLine("ODOM 1 2 3").has_value());
  EXPECT_FALSE(ParseCommandLine("").has_value());
}

TEST(ChassisPacketTest, ParsePacketLineOdometryWithBattery) {
