      0x01, (uint8_t)0xf4,  // 500
      0x00, (uint8_t)0x2c,  // 44
      0x00, 0x00,           // 0
      0x09, (uint8_t)0xc4,  // 2500 → 25.00V
  };
  const auto packet = DecodeMickBinaryPacket(frame);
