  EXPECT_EQ(packet->kind, ChassisPacketKind::kOdometry);
  EXPECT_NEAR(packet->odometry.x_m, 1.0, 1e-9);
  ASSERT_TRUE(packet->odometry.battery_voltage.has_value());
  EXPECT_NEAR(*packet->odometry.battery_voltage, 25.0, 1e-9);
