  for (int i = 0; i < 8; ++i) {
    t.NextSequence();
  }
  t.OnEcho(0);
  t.OnEcho(5);
  // 已确认 5；0..5 共 6 帧送达，8 帧窗口
  EXPECT_NEAR(t.DeliveryRate(), 6.0 / 8.0, 1e-9);
  EXPECT_EQ(t.DeliveredCount(), 6u);
}

