99	void PathTrackerNode::PathCallback(const nav_msgs::msg::Path::SharedPtr msg) {
100	  // /plan 由 dispatcher 在 map 帧发布；本节点没有 tf 依赖，若对端换成了别的帧
101	  // （例如未配置 odom_origin_* 却收到 odom 帧的路径），这里只告警不猜测转换，
102	  // 避免静默算错方向。空 frame_id 视为未约定，与旧行为一致。
103	  if (!msg->header.frame_id.empty() && msg->header.frame_id != "map" &&
104	      !warned_frame_mismatch_) {
105	    warned_frame_mismatch_ = true;
106	    RCLCPP_WARN(get_logger(),
107	                "Path frame_id is '%s' but positions are applied on the map frame "
108	                "(odom_origin_x=%.3f y=%.3f yaw=%.3f). Check odom_origin_* parameters.",
109	                msg->header.frame_id.c_str(), odom_origin_x_, odom_origin_y_,
110	                odom_origin_yaw_);
111	  }
112	  waypoints_.clear();
113	  for (const auto& pose_stamped : msg->poses) {
114	    amr_dispatcher_core::path_tracking::Pose2D wp;
115	    wp.x = pose_stamped.pose.position.x;
116	    wp.y = pose_stamped.pose.position.y;
117	    wp.yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
118	        pose_stamped.pose.orientation.z, pose_stamped.pose.orientation.w);
119	    waypoints_.push_back(wp);
120	  }
121	  has_path_ = !waypoints_.empty();
122	  if (pp_controller_) pp_controller_->SetPath(waypoints_);
123	  if (stanley_controller_) stanley_controller_->SetPath(waypoints_);
124	  RCLCPP_INFO(get_logger(), "Received path with %zu waypoints", waypoints_.size());
125	}
126	
127	void PathTrackerNode::OdomCallback(const nav_msgs::msg::Odometry::SharedPtr msg) {
128	  // 把 odom 帧下的位姿搬进 map 帧：先按 odom_origin_yaw 旋转，再平移。
129	  // 偏移全 0 时结果与旧实现逐位相同（单车仿真兼容）。
130	  const double raw_x = msg->pose.pose.position.x;
131	  const double raw_y = msg->pose.pose.position.y;
132	  const double raw_yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
133	      msg->pose.pose.orientation.z, msg->pose.pose.orientation.w);
134	  const double c = std::cos(odom_origin_yaw_);
135	  const double s = std::sin(odom_origin_yaw_);
136	  current_pose_.x = odom_origin_x_ + raw_x * c - raw_y * s;
137	  current_pose_.y = odom_origin_y_ + raw_x * s + raw_y * c;
138	  current_pose_.yaw = std::atan2(std::sin(raw_yaw + odom_origin_yaw_),
139	                                 std::cos(raw_yaw + odom_origin_yaw_));
140	  current_linear_speed_ = msg->twist.twist.linear.x;
141	  has_odom_ = true;
142	}
143	
144	void PathTrackerNode::ControlLoop() {
145	  // B1：心跳必须无条件先发——idle 早退若挡在心跳前，安全门会误判本节点失联。
146	  if (heartbeat_pub_) {
147	    std_msgs::msg::Bool hb;
148	    hb.data = true;
149	    heartbeat_pub_->publish(hb);
150	  }
151	
152	  if (!has_odom_ || !has_path_ || waypoints_.empty()) {
153	    return;
154	  }
155	
156	  geometry_msgs::msg::Twist cmd;
157	  amr_dispatcher_interfaces::msg::TrackingError err_msg;
158	  err_msg.header.stamp = now();
159	  err_msg.controller_name = controller_type_;
160	
161	  if (controller_type_ == "stanley") {
162	    auto res = stanley_controller_->Compute(current_pose_);
163	    cmd.linear.x = res.cmd.linear_x;
164	    cmd.angular.z = res.cmd.angular_z;
165	
166	    err_msg.lateral_error_m = res.lateral_error;
167	    err_msg.heading_error_rad = res.heading_error;
168	    err_msg.target_linear_x_mps = res.cmd.linear_x;
169	    err_msg.target_angular_z_radps = res.cmd.angular_z;
170	    err_msg.actual_linear_x_mps = current_linear_speed_;
171	    err_msg.nearest_waypoint_index = static_cast<int32_t>(res.nearest_index);
172	    err_msg.arrived = res.goal_reached;
173	  } else {
174	    auto res = pp_controller_->Compute(current_pose_);
175	    cmd.linear.x = res.cmd.linear_x;
176	    cmd.angular.z = res.cmd.angular_z;
177	
178	    err_msg.lateral_error_m = res.lateral_error;
179	    err_msg.heading_error_rad = res.heading_error;
180	    err_msg.target_linear_x_mps = res.cmd.linear_x;
181	    err_msg.target_angular_z_radps = res.cmd.angular_z;
182	    err_msg.actual_linear_x_mps = current_linear_speed_;
183	    err_msg.nearest_waypoint_index = static_cast<int32_t>(res.nearest_index);
184	    err_msg.arrived = res.goal_reached;
185	  }
186	
187	  cmd_vel_pub_->publish(cmd);
188	  error_pub_->publish(err_msg);
189	
190	  if (err_msg.arrived) {
191	    RCLCPP_INFO_THROTTLE(get_logger(), *get_clock(), 2000, "Goal reached, stopping robot");
192	    has_path_ = false;
193	  }
194	}
195	
196	}  // namespace amr_dispatcher_ros
197	
198	int main(int argc, char* argv[]) {
199	  rclcpp::init(argc, argv);

