  if (!msg || !msg->data) {
    return;
  }
  // I1：心跳到达即打点（真实数据到达点，而非巡检周期）
  last_data_arrival_["watchdog"] = std::chrono::steady_clock::now();
  // B1 分源喂狗：只 Feed 回调登记的来源，watched_nodes_ 里每个源独立计时。
  if (watchdog_) {
