  // 真机却从编码器 0 开始 —— 车放在 A 站，odom 是 (0,0,0) 而 map 认为 A 在 (1,2)，
  // 于是车会朝反方向开出 2 米多。给一台位置固定的台架，这层偏移就是常量。
  double odom_origin_x_ = 0.0;
  double odom_origin_y_ = 0.0;
  double odom_origin_yaw_ = 0.0;
  bool warned_frame_mismatch_ = false;

