  amr_dispatcher_core::safety::CmdVelGateDecision last_decision_{};
  // 最近一次 /cmd_vel_raw（含手动接管转发的 teleop）接收时刻，B1 上游失联兜底判 stale 用
  std::chrono::steady_clock::time_point last_raw_cmd_stamp_{};
